package org.apache.commons.math3.dfp;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math3.FieldElement;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class Dfp_multiply_TriageGen4Test {

    private Dfp dfpInstance;

    @Before
    public void setUp() {
        // Using newInstance() to get a valid Dfp instance from the field
        dfpInstance = Dfp.newInstance();
    }

    @Test
    public void testMultiply_PositiveInteger() {
        int x = 5;
        Dfp result = dfpInstance.multiply(x);

        // Expected: dfpInstance * 5. Since dfpInstance is default (usually 1.0 or similar), 
        // we test against a known value.
        Dfp expected = dfpInstance.newInstance(5.0); 
        // Note: The behavior of multiply(int) on Dfp is essentially dfp * x.
        // If dfpInstance is 1.0, result is 5.0.

        // Since we don't know the exact initial value of newInstance(), 
        // we verify the mathematical property: result / x should be original dfp
        // or more simply, if we start with 1.0:
        Dfp one = dfpInstance.getOne();
        Dfp resultWithOne = one.multiply(x);
        assertEquals(new Dfp(one.newInstance(x.doubleValue())), resultWithOne);
    }

    @Test
    public void testMultiply_Zero() {
        int x = 0;
        Dfp result = dfpInstance.multiply(x);

        // Any Dfp multiplied by 0 should be 0
        assertTrue(result.isZero());
    }

    @Test
    public void testMultiply_NegativeInteger() {
        int x = -10;
        Dfp result = dfpInstance.multiply(x);

        Dfp one = dfpInstance.getOne();
        Dfp expected = one.multiply(-10.0); // Using double version to verify

        // Check sign
        assertTrue(result.strictlyNegative());

        // Verify against a known calculation
        Dfp testVal = dfpInstance.newInstance(2.0);
        Dfp resultVal = testVal.multiply(-10);
        assertEquals(new Dfp(testVal.newInstance(-20.0)), resultVal);
    }

    @Test
    public void testMultiply_LargeInteger() {
        int x = Integer.MAX_VALUE;
        Dfp result = dfpInstance.multiply(x);

        assertNotNull(result);

        Dfp one = dfpInstance.getOne();
        Dfp expected = one.newInstance((double) x);
        assertEquals(expected, one.multiply(x));
    }

    @Test
    public void testMultiply_SmallInteger() {
        int x = 1;
        Dfp result = dfpInstance.multiply(x);

        // multiplying by 1 should return the same value
        // Note: Dfp equality might be sensitive to precision, but for integer 1 it should hold
        assertEquals(dfpInstance.getOne(), dfpInstance.newInstance(1.0));
        Dfp res = dfpInstance.multiply(1);
        // Verify result is logically equal to original
        // Since we can't use equals directly on doubles easily, we check via scale/value if possible
        // but here we check if result is equal to dfpInstance * 1
        Dfp expected = dfpInstance.multiply(dfpInstance.getOne().intValue());
        // The method multiply(int) is specifically for integer multiplication
    }

    @Test
    public void testMultiply_IdentityWithOne() {
        Dfp one = dfpInstance.getOne();
        Dfp result = one.multiply(1);
        assertEquals(one, result);
    }

    @Test
    public void testMultiply_Consistency() {
        // Testing that multiply(x) is consistent with multiply(Dfp x)
        int x = 42;
        Dfp resultInt = dfpInstance.multiply(x);
        Dfp resultDfp = dfpInstance.multiply(dfpInstance.newInstance(x));

        assertEquals(resultInt, resultDfp);
    }
}
